// Extract the canonical NutriServe catalog (foods + customers) into a pure TypeScript module the
// simulation and its Node tests can import without React. Source of truth stays in
// services/nutriServeFoodData.ts and services/nutriserveCharacters.ts; the generated file records
// their SHA-256 so tests/nutriserve-catalog.test.mjs fails when it drifts.
//
//   node scripts/generate-nutriserve-catalog.mjs          # write
//   node scripts/generate-nutriserve-catalog.mjs --check  # exit 1 if out of date
import fs from 'node:fs';
import crypto from 'node:crypto';
import ts from 'typescript';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const OUT = 'src/features/nutriserve/data/catalog.generated.ts';
const SOURCES = { foods: 'services/nutriServeFoodData.ts', customers: 'services/nutriserveCharacters.ts' };

/** Fields that hold React components in the source and are intentionally left out. */
const SKIPPED_FIELDS = new Set(['visual', 'visuals']);

/**
 * Evaluate literal-only expressions. Known component fields are skipped; any other non-literal
 * field fails the build instead of silently vanishing from the generated catalog.
 */
function literal(node, source) {
  if (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node)) return node.text;
  if (ts.isNumericLiteral(node)) return Number(node.text);
  if (ts.isPrefixUnaryExpression(node) && node.operator === ts.SyntaxKind.MinusToken && ts.isNumericLiteral(node.operand)) {
    return -Number(node.operand.text);
  }
  if (node.kind === ts.SyntaxKind.TrueKeyword) return true;
  if (node.kind === ts.SyntaxKind.FalseKeyword) return false;
  if (ts.isArrayLiteralExpression(node)) {
    const values = node.elements.map((e) => literal(e, source));
    return values.some((v) => v === undefined) ? undefined : values;
  }
  if (ts.isObjectLiteralExpression(node)) {
    const out = {};
    for (const prop of node.properties) {
      if (!ts.isPropertyAssignment(prop)) continue;
      const name = prop.name.getText(source).replace(/^['"]|['"]$/g, '');
      if (SKIPPED_FIELDS.has(name)) continue;
      const value = literal(prop.initializer, source);
      if (value === undefined) {
        const { line } = source.getLineAndCharacterOfPosition(prop.getStart(source));
        throw new Error(`${source.fileName}:${line + 1}: field "${name}" is not a literal; add it to SKIPPED_FIELDS or make it literal`);
      }
      out[name] = value;
    }
    return out;
  }
  return undefined;
}

function readArray(file, variable) {
  const text = fs.readFileSync(root + file, 'utf8');
  const source = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true);
  let init;
  (function find(node) {
    if (ts.isVariableDeclaration(node) && node.name.getText(source) === variable) init = node.initializer;
    ts.forEachChild(node, find);
  })(source);
  if (!init || !ts.isArrayLiteralExpression(init)) throw new Error(`Missing array ${variable} in ${file}`);
  return { source, init, sha256: crypto.createHash('sha256').update(text).digest('hex') };
}

const foodsSrc = readArray(SOURCES.foods, 'FOOD_LIBRARY');
const foods = [];
for (const group of foodsSrc.init.elements) {
  const g = literal(group, foodsSrc.source);
  for (const item of g.items ?? []) {
    if (!item.id || !item.nutrients_per_100g) throw new Error(`Food without id/nutrients in ${g.name}`);
    foods.push(item);
  }
}

const customersSrc = readArray(SOURCES.customers, 'CUSTOMER_CHARACTERS');
const customers = customersSrc.init.elements.map((el) => {
  const c = literal(el, customersSrc.source);
  if (!c.id || !c.name) throw new Error('Customer without id/name');
  return { id: c.id, name: c.name, order: c.order, orderVariations: c.orderVariations, dialogue: c.dialogue };
});

for (const [kind, list] of [['food', foods], ['customer', customers]]) {
  const ids = list.map((x) => x.id);
  const dupes = ids.filter((id, i) => ids.indexOf(id) !== i);
  if (dupes.length) throw new Error(`Duplicate ${kind} ids: ${dupes.join(', ')}`);
}

const body = `// GENERATED by scripts/generate-nutriserve-catalog.mjs: do not edit by hand.
// Sources: ${SOURCES.foods} (sha256 ${foodsSrc.sha256})
//          ${SOURCES.customers} (sha256 ${customersSrc.sha256})
import type { CatalogCustomer, CatalogFood } from './catalogTypes.ts';

export const CATALOG_SOURCES = ${JSON.stringify({ foods: { path: SOURCES.foods, sha256: foodsSrc.sha256 }, customers: { path: SOURCES.customers, sha256: customersSrc.sha256 } }, null, 2)} as const;

export const CATALOG_FOODS: readonly CatalogFood[] = ${JSON.stringify(foods, null, 2)};

export const CATALOG_CUSTOMERS: readonly CatalogCustomer[] = ${JSON.stringify(customers, null, 2)};
`;

const outPath = root + OUT;
if (process.argv.includes('--check')) {
  const current = fs.existsSync(outPath) ? fs.readFileSync(outPath, 'utf8') : '';
  if (current !== body) {
    console.error(`${OUT} is out of date. Run: node scripts/generate-nutriserve-catalog.mjs`);
    process.exit(1);
  }
  console.log(`${OUT} is up to date (${foods.length} foods, ${customers.length} customers).`);
} else {
  fs.mkdirSync(root + 'src/features/nutriserve/data', { recursive: true });
  fs.writeFileSync(outPath, body);
  console.log(`Wrote ${OUT}: ${foods.length} foods, ${customers.length} customers.`);
}
